import type { SandboxJson, SandboxSdk } from '@molis/plugin-sdk';

type CountResult = {
  characters: number;
  utf8_bytes: number;
  lines: number;
};

/**
 * One pass over the text: counts Unicode code points (so an astral character
 * such as an emoji counts once, not as its two UTF-16 units) and the UTF-8
 * bytes those code points encode to.
 */
function countCodePointsAndBytes(text: string): { characters: number; utf8_bytes: number } {
  let characters = 0;
  let utf8Bytes = 0;
  for (const symbol of text) {
    characters += 1;
    const codePoint = symbol.codePointAt(0) ?? 0;
    if (codePoint <= 0x7f) utf8Bytes += 1;
    else if (codePoint <= 0x7ff) utf8Bytes += 2;
    else if (codePoint <= 0xffff) utf8Bytes += 3;
    else utf8Bytes += 4;
  }
  return { characters, utf8_bytes: utf8Bytes };
}

/** Lines are the segments between LF characters; an empty text is one empty segment. */
function countLines(text: string): number {
  return text.split('\n').length;
}

export default async function operation(input: SandboxJson, _sdk: SandboxSdk): Promise<SandboxJson> {
  const raw = (input as { text?: unknown }).text;
  const text = typeof raw === 'string' ? raw : '';
  const { characters, utf8_bytes } = countCodePointsAndBytes(text);
  const result: CountResult = {
    characters,
    utf8_bytes,
    lines: countLines(text),
  };
  return result;
}

