import type { SandboxTest } from '@molis/plugin-sdk';

export const tests: SandboxTest[] = [
  // The frozen example: mixed Chinese and ASCII around one LF.
  async (_sdk, call, assert) => {
    const result = await call({ text: '一行\nline' });
    assert.same(result, { characters: 7, utf8_bytes: 11, lines: 2 });
  },
  // An empty text is one empty line and no characters or bytes.
  async (_sdk, call, assert) => {
    const result = await call({ text: '' });
    assert.same(result, { characters: 0, utf8_bytes: 0, lines: 1 });
  },
  // Code points, not UTF-16 units: the emoji is one character and four bytes.
  async (_sdk, call, assert) => {
    const result = await call({ text: '😀汉a' });
    assert.same(result, { characters: 3, utf8_bytes: 8, lines: 1 });
  },
  // A combining mark is its own code point, so the pair is two characters.
  async (_sdk, call, assert) => {
    const result = await call({ text: 'e\u0301' });
    assert.same(result, { characters: 2, utf8_bytes: 3, lines: 1 });
  },
  // A trailing LF opens one more (empty) segment.
  async (_sdk, call, assert) => {
    const result = await call({ text: 'a\n' });
    assert.same(result, { characters: 2, utf8_bytes: 2, lines: 2 });
  },
  // Blank lines in the middle count as segments of their own.
  async (_sdk, call, assert) => {
    const result = await call({ text: 'a\n\nb' });
    assert.same(result, { characters: 4, utf8_bytes: 4, lines: 3 });
  },
  // Only LF breaks a line; CR stays an ordinary character.
  async (_sdk, call, assert) => {
    const result = await call({ text: 'a\r\nb' });
    assert.same(result, { characters: 4, utf8_bytes: 4, lines: 2 });
  },
  // A missing text is treated as the empty text instead of failing.
  async (_sdk, call, assert) => {
    const result = await call({});
    assert.same(result, { characters: 0, utf8_bytes: 0, lines: 1 });
  },
  // The same text always gives the same three numbers, and nothing else.
  async (_sdk, call, assert) => {
    const first = await call({ text: '一行\nline' });
    const second = await call({ text: '一行\nline' });
    assert.same(second, first);
    assert.same(Object.keys(first as Record<string, unknown>).sort(), ['characters', 'lines', 'utf8_bytes']);
  },
];
